package com.backend.nutri_predic.plandia.dto; import com.backend.nutri_predic.plandia.entity.*; import java.time.LocalDate; public record CumplimientoDiarioResponse(Long planId,LocalDate fecha,ComponenteCumplimientoResponse energia,ComponenteCumplimientoResponse proteina,ComponenteCumplimientoResponse carbohidratos,ComponenteCumplimientoResponse grasas){public static CumplimientoDiarioResponse from(CumplimientoDiario x){var p=x.getPlan();return new CumplimientoDiarioResponse(p.getId(),p.getFechaObjetivo(),c(p.getEnergiaMinKcal(),p.getEnergiaMaxKcal(),x.getEnergiaConsumido(),x.getEnergiaDiferencia(),x.getEnergiaPorcentaje(),x.getEnergiaEstado()),c(p.getProteinaMinG(),p.getProteinaMaxG(),x.getProteinaConsumido(),x.getProteinaDiferencia(),x.getProteinaPorcentaje(),x.getProteinaEstado()),c(p.getCarbohidratosMinG(),p.getCarbohidratosMaxG(),x.getCarbohidratosConsumido(),x.getCarbohidratosDiferencia(),x.getCarbohidratosPorcentaje(),x.getCarbohidratosEstado()),c(p.getGrasasMinG(),p.getGrasasMaxG(),x.getGrasasConsumido(),x.getGrasasDiferencia(),x.getGrasasPorcentaje(),x.getGrasasEstado()));}private static ComponenteCumplimientoResponse c(java.math.BigDecimal min,java.math.BigDecimal max,java.math.BigDecimal con,java.math.BigDecimal dif,java.math.BigDecimal por,EstadoCumplimientoComponente est){return new ComponenteCumplimientoResponse(min,max,con,dif,por,est.name());}}
